-- Listings and compliance checks for the 30 seed dealerships.
-- Generated by scripts/gen_listings.py from contract/*.json; do not hand-edit.
-- Ad copy describes the real Kijiji listing behind each vehicle (see kijiji_url in
-- contract/vehicles-plan.json). rule_findings follow DealerOps.Core/Compliance/OmvicRuleEngine.cs.
SET NAMES utf8mb4;

-- D01 2015 Mazda Mazda3 (CERTIFIED): CASH / ONLINE -> PASSED
SET @d = (SELECT id FROM dealer WHERE contact_email = 'sales@lakeshoreautosales.ca');
SET @v = (SELECT id FROM vehicle WHERE dealer_id = @d AND vin = '3MZBM1L75FM193583');
INSERT INTO listing (dealer_id, vehicle_id, title, body, ad_kind, medium, prior_use, warranty_terms,
    annual_km_allowance, status, content_version, last_check_id, version, created_at, updated_at)
SELECT @d, @v, 'Certified 2015 Mazda Mazda3 GS | 132,664 km | $12,495',
    'Used 2015 Mazda Mazda3 GS, FWD, 132,664 km. Ontario safety certified with a fresh oil change, inspection report on file, and two keys. All-in price $12,495 plus HST and licensing. Lakeshore Auto Sales Ltd., 1192 Queen St E, Toronto, ON M8H 2Y8. Call (416) 555-0197 or email sales@lakeshoreautosales.ca.',
    'CASH', 'ONLINE', NULL, NULL,
    NULL, 'READY', 1, NULL, 2, '2026-01-09 18:45:00', '2026-01-09 18:55:06'
FROM DUAL WHERE @v IS NOT NULL AND NOT EXISTS (SELECT 1 FROM listing WHERE vehicle_id = @v);
SET @l = (SELECT id FROM listing WHERE vehicle_id = @v);
INSERT INTO compliance_check (dealer_id, listing_id, content_version, rule_findings, ai_status,
    ai_notes, recommendation, created_at)
SELECT @d, @l, 1,
    '[]',
    'SUCCESS',
    '[{"message": "No additional misleading claims found."}]',
    'PASSED', '2026-01-09 18:55:06'
FROM DUAL WHERE @l IS NOT NULL AND NOT EXISTS (SELECT 1 FROM compliance_check WHERE listing_id = @l AND created_at = '2026-01-09 18:55:06');
UPDATE listing SET last_check_id = (SELECT id FROM compliance_check WHERE listing_id = @l AND created_at = '2026-01-09 18:55:06'),
    updated_at = updated_at WHERE id = @l AND last_check_id IS NULL;

